import json, os
from pathlib import Path

def summarize_jsonl(path):
    print("\n====", path, "====")
    with open(path) as f:
        lines = f.readlines()
    print("nlines", len(lines), "bytes", os.path.getsize(path))
    for i, line in enumerate(lines):
        obj = json.loads(line)
        print("--- record", i, "keys", sorted(obj.keys()))
        for k,v in obj.items():
            if isinstance(v, str):
                print(f"  {k}: str len={len(v)} preview={v[:180]!r} ... tail={v[-180]!r}")
            elif isinstance(v, (int, float, bool)) or v is None:
                print(f"  {k}: {v}")
            elif isinstance(v, list):
                print(f"  {k}: list len={len(v)} type0={type(v[0]).__name__ if v else None}")
                if v and isinstance(v[0], (int, float)):
                    print(f"    first10={v[:10]} last10={v[-10:]}")
                elif v and isinstance(v[0], str):
                    print(f"    first item len={len(v[0])} preview={v[0][:120]!r}")
                elif v and isinstance(v[0], dict):
                    print(f"    item0 keys={list(v[0].keys())[:30]}")
            elif isinstance(v, dict):
                print(f"  {k}: dict keys={list(v.keys())[:40]}")
            else:
                print(f"  {k}: {type(v)}")

for p in [
    "experiment_logs/validation/0.jsonl",
    "experiment_logs/validation/1.jsonl",
    "experiment_logs/validation/2.jsonl",
    "experiment_logs/rollouts/1.gen_001.jsonl",
    "experiment_logs/rollouts/2.gen_001.jsonl",
]:
    summarize_jsonl(p)
