# generation records structure
for p in ["generation_records/engine-requests.json","generation_records/heldout-responses.json"]:
    print("====", p, os.path.getsize(p))
    with open(p) as f:
        data = json.load(f)
    print(type(data), len(data) if hasattr(data,'__len__') else None)
    if isinstance(data, dict):
        print("keys", list(data.keys())[:30])
        data_list = data.get("requests") or data.get("records") or data.get("responses") or list(data.values())[0]
        if not isinstance(data_list, list):
            # print nested
            for k,v in data.items():
                print(" ", k, type(v).__name__, (len(v) if hasattr(v,'__len__') and not isinstance(v,str) else str(v)[:200]))
            continue
    else:
        data_list = data
    print("n", len(data_list), "item0 type", type(data_list[0]).__name__)
    if isinstance(data_list[0], dict):
        print("item0 keys", list(data_list[0].keys()))
        for i, item in enumerate(data_list):
            print("--- item", i)
            for k,v in item.items():
                if isinstance(v, str):
                    print(f"  {k}: str {len(v)} head={v[:150]!r} tail={v[-120]!r}")
                elif isinstance(v, list):
                    print(f"  {k}: list {len(v)}", end=" ")
                    if v and isinstance(v[0], int):
                        print(f"first={v[:8]} last={v[-8:]} uniq_tail={Counter(v[-20:]).most_common(5)}")
                    elif v and isinstance(v[0], float):
                        print(f"first={v[:3]} last={v[-3:]}")
                    else:
                        print(type(v[0]).__name__ if v else "")
                elif isinstance(v, dict):
                    print(f"  {k}: dict keys {list(v.keys())[:20]}")
                else:
                    print(f"  {k}: {v}")
